"""1621 (#115): Test-CarryBody-v1442.ps1 with the Far Reach target read. In 1427a, 1430b and 1442a Emily's Far Reach at an
unconscious body ran pullIn and pullOut without the pull loop and the body stayed put; whether the body was ever the
power's target was not read. Object pulls showed where to read it (object-carry-v1616b): arkCpntPowerGrapple (UsePower 63
+0x60) holds the aimed entity's handle at +0xdc, and GrabGrappledEntity (84) holds the pulled one at +0x38. The aim sweep
and every pull try now sample, about every 100 ms, the active player states, the aimed and pulled handles and the body's
NPC authority entry in the client's stream (result, unconscious, ready). The three tries run their trigger hold in the
background so the samples cover the release and the pull. Generated by make_carry_body_v1621.py."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Test-CarryBody-v1442.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
lines = s.split('\n')
lines.insert(2, "# 1621 (#115): the aim sweep and the pull tries sample the Far Reach target handles and the body's NPC entry. Generated by make_carry_body_v1621.py.")
s = '\n'.join(lines)
rep("     $row.bodyHandle=try{(Guard $source).handle}catch{$null};$dumps=[Collections.Generic.List[object]]::new()",
    "     $row.bodyHandle=try{(Guard $source).handle}catch{$null};$dumps=[Collections.Generic.List[object]]::new()\n"
    "     # 1621: the aimed handle (arkCpntPowerGrapple +0xdc through UsePower 63 +0x60) and the pulled one (84 +0x38).\n"
    "     $aimTarget={$agPs=try{Q $source '--player-states'}catch{$null};if(!$agPs){return $null};$agOut=[ordered]@{active=@($agPs.active|ForEach-Object {$_.id});aim=$null;pulled=$null}\n"
    "      foreach($agId in 63,84){if(!@($agPs.active|Where-Object {$_.id-eq$agId}).Count){continue}\n"
    "       $agSlot='0x{0:x}' -f ([Convert]::ToUInt64(($agPs.mode-replace'^0x',''),16)+0x10+$agId*8);$agState=try{(Q $source '--object' $agSlot).words[0].word}catch{$null};if(!$agState){continue}\n"
    "       $agWords=try{(Q $source '--object' $agState).words}catch{$null};if(!$agWords){continue}\n"
    "       if($agId-eq84){$agWord=@($agWords|Where-Object {$_.offset-eq'0x38'});if($agWord.Count){$agOut.pulled='0x{0:x}' -f ([Convert]::ToUInt64(($agWord[0].word-replace'^0x',''),16)-band[uint64]4294967295)}}\n"
    "       else{$agPw=@($agWords|Where-Object {$_.offset-eq'0x60'-and$_.pointerType-eq'.?AVarkCpntPowerGrapple@@'});if($agPw.Count){$agWord=@($(try{(Q $source '--object' $agPw[0].word).words}catch{@()})|Where-Object {$_.offset-eq'0xd8'})\n"
    "        if($agWord.Count){$agOut.aim='0x{0:x}' -f ([Convert]::ToUInt64(($agWord[0].word-replace'^0x',''),16)-shr 32)}}}}\n"
    "      [pscustomobject]$agOut}\n"
    "     $bodyEntry={$agEntry=@($(try{(S $source '.npc-stream.json').entries}catch{@()})|Where-Object {('0x{0:x}' -f [uint32]$_.handle)-eq$row.bodyHandle})\n"
    "      if($agEntry.Count){[pscustomobject]@{result=$agEntry[0].result;unconscious=$agEntry[0].unconscious;ready=$agEntry[0].ready;poses=$agEntry[0].poses}}else{$null}}")
rep("grapple=$(try{Q $source '--player-grapple'}catch{$null})})}",
    "grapple=$(try{Q $source '--player-grapple'}catch{$null});target=$(& $aimTarget);npc=$(& $bodyEntry)})}")
rep("      & \"$lab/Send-D2Input.ps1\" -Role $source -LeftTrigger 255 -DurationMs 2600|Out-Null;Start-Sleep -Milliseconds 1800",
    "      $ltq=Start-Process (Get-Process -Id $PID).Path -ArgumentList @('-NoProfile','-File',\"$lab/Send-D2Input.ps1\",'-Role',$source,'-LeftTrigger','255','-DurationMs','2600') -WindowStyle Hidden -PassThru\n"
    "      $pullSamples=[Collections.Generic.List[object]]::new();$pw2=[Diagnostics.Stopwatch]::StartNew()\n"
    "      while($pw2.ElapsedMilliseconds-lt4400){$pullSamples.Add([pscustomobject]@{ms=$pw2.ElapsedMilliseconds;target=$(& $aimTarget);npc=$(& $bodyEntry);body=$(try{(Guard $source).position}catch{$null})});Start-Sleep -Milliseconds 40}\n"
    "      try{$ltq.WaitForExit(5000)|Out-Null}catch{};Save \"$out/$key-farreach-try$k.json\" @($pullSamples)\n"
    "      $row.\"farReachTry${k}Aimed\"=@($pullSamples|ForEach-Object {$_.target.aim}|Where-Object {$_}|Select-Object -Unique);$row.\"farReachTry${k}Pulled\"=@($pullSamples|ForEach-Object {$_.target.pulled}|Where-Object {$_}|Select-Object -Unique)")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Test-CarryBody-v1621.ps1').write_bytes(out.encode('utf-8'))
print('ok')
